def count_substrings(s):
    n = len(s)
    dp = [0] * n
    dp[0] = 1  # Empty string is distinct

    for i in range(1, n):
        # Check if the string ending with s[i-1] is already explained by the string ending with a star
        if s[i-1] == '*':
            dp[i] = dp[i-1] * 2 + 1  # Explained by string ending with star, and a new string ending with s[i-1]
        else:
            # Explained by a string ending with the same letter, and a new string ending with s[i-1]
            dp[i] = dp[i-1] * 2

    return dp[-1] if n > 1 else 1

def distinct_strings_count(s):
    return count_substrings(s)

