def find_parents(parents, child):
    parent_of = defaultdict(list)
    for i in range(1, len(parents)):
        parent = parents[i]
        if parent != child and parents[parent] == (parent + 1) // 2:
            parent_of[child].append(parent)
            if child != parent:
                parent_of[parent].append(child)
