from collections import defaultdict, Counter

def smallest_string(S):
    count = Counter(S)
    smallest = ''.join([k if count[k] % 2 == 0 else k + k for k in 'abcdefghijklmnopqrstuvwxyz'])
    left, right = count, defaultdict(int)
    for char in smallest:
        if left[char] > 0:
            left[char] -= 1
            right[char] += 1
        if right[char] == 0:
            left.pop(char)
    return ''.join(sorted([k * (left[k] // 2) for k in 'abcdefghijklmnopqrstuvwxyz']))

