def find_parent(child, parent):
    if child == -1:
        return None
    if parent == -1:
        return None

    if child == parent:
        return None

    while parent != -1:
        if child == parent:
            return None
        child = parent
        parent = int(parent / 2)

    return None

def get_parent_type(parent_obj):
    parent_type = 0
    current = find_parent(parent_obj, -1)

    if current is not None:
        while current is not None:
            parent_type += 1
            current = find_parent(current, -1)

    return parent_type

def chase_node(parent_obj, current_obj, step):
    if current_obj is None or parent_obj is None:
        return False

    if current_obj == parent_obj:
        return True

    while step > 0:
        current_obj = int(current_obj / 2)
        step -= 1

    return chase_node(parent_obj, current_obj, step)

