def bfs(graph, start, end):
    visited = [False] * len(graph)
    queue = [(start, 0)]

    while queue:
        current, level = queue.pop(0)
        if current == end:
            return level + 1
        if visited[current]:
            continue
        visited[current] = True

        for neighbour in graph[current]:
            if not visited[neighbour]:
                queue.append((neighbour, level + 1))

    return -1

def find_path(edges, u, v):
    parent = [-1] * (len(edges) + 1)
    dp = [-1] * (len(edges) + 1)

    visited = [False] * (len(edges) + 1)
    queue = [u]

    while queue:
        current = queue.pop(0)
        visited[current] = True

        if current == v:
            break

        for edge in edges[current]:
            if visited[edge] or dp[edge] == -1:
                continue

            if dp[edge] == -1:
                parent[edge] = current
                dp[edge] = dp[current] - 1

            queue.append(edge)

    path = [v]
    while v != -1:
        v = parent[v]
        path.append(v)

    path.reverse()

    return path

def is_bfs_possible(start, end, adj_list, dp=[]):
    queue_count = [[start, -1], [0, -1]]
    order = 0

    while queue_count:
        queue = queue_count.pop(0)

        current = queue[0]
        queue_order = queue[1]

        add_to_queue = True

        for adj in adj_list[current]:
            if queue_order < dp[adj]:
                queue_order = dp[adj]
                add_to_queue = False

            elif not visited[adj]:
                visited[adj] = True
                queue += [[adj, queue_order], [adj, 0]]
                add_to_queue = False

        if add_to_queue:
            order += 1
            queue += [[current, 0]]

    return order, end

