        return True
    for sibling in range(1, child):
        types[sibling-1] = -1  # Marking siblings
        if types[sibling-1] == 1:
            return True
    return False

def is_part_of(parent, child, types):
    if child == -1 or parent == -1:
        return False
    types[child-1] = -1  # Marking as computed
    if types[child-1] == 1:
        return True
    types[parent-1] = -1  # Marking parent
    for sibling in range(1, child):
        if types[sibling-1] == 1:
            return True
    return False

