from collections import defaultdict

def count_distinct_substrings(s):
    n = len(s)

    # Initialize DP table with a seed value
    DP = defaultdict(set)
    DP[0] = {s[0]}

    for i in range(1, 27):
        # Convert current 'seed' character (in base 26) to decimal
        seed = (ord('a') + i - 1) // 26
        for string in DP[seed]:
            for c in range(1, 27):
                # Check if adding current character 'c' forms a valid substring
                if s[26 * n + c] > 'a':
                    new_string = string + s[n - c * 26]
                    if new_string not in DP[c]:
                        DP[c].add(new_string)

    return len(DP[26])

