from collections import defaultdict

class Graph:
    def __init__(self, n):
        self.graph = defaultdict(list)
        self.visited = [False] * (n + 1)
        self.backward_chain = {}

    def add_edge(self, u, v):
        if u < v:
            self.graph[u].append(v)
            self.add_edge(u, v)
        elif v < u:
            self.graph[v].append(u)
            self.add_edge(u, v)

    def add_backward_edge(self, parent, child):
        if parent > child:
            self.backward_chain[child] = parent
            self.add_backward_edge(parent, child)

    def process_query(self, typei, u, v):
        if typei == 1:  # Special case query
            if u not in self.backward_chain:
                return "YES"
            while u > 1:
                if v in self.backward_chain[u]:
                    return "YES"
                    break
                u = self.backward_chain[u]
            return "NO"
        elif typei == 2:  # Part query
            if u in self.backward_chain and v in self.graph[u]:
                return "YES"
                break
            return "NO"

    def depth_first_search(self, node):
        self.visited[node] = True
        for child in self.graph[node]:
            if not self.visited[child]:
                self.depth_first_search(child)

    def build_graph(self):
        for parent, type in self.parents:
            u = self.parents.index((parent, type))
            v = u + 1
            if self.parents[parent] == -1:
                v = 0
            if type == 0:
                if u > 1:
                    self.backward_chain[u] = self.parents[p_index - 1]
                    u -= 1
                self.parents[v] = u
            elif type == 1:
                self.backward_chain[v] = self.parents[parent]

    def solve_queries(self, queries):
        for query in queries:
            self.depth_first_search(query[1]) if query[0] == 1 else self.depth_first_search(query[2])

# Read input
